INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b255ba9b-992e-48d9-8df2-0090a357af0b', 'Late Fees', '3', '4', 'CONTRAPRESTACIÓN', E'- If the subtenant does not pay the rent within the first ten days of the month, late interest will start to accumulate from the eleventh day.\n- The late interest rate is 4% per month, calculated for the time the payment is overdue.\n- If there are outstanding rent or interest payments, any payment made by the subtenant will first cover the interest, and any remaining amount will go towards the overdue rent.', 'En caso de que EL SUBARRENDATARIO no realice el pago de la Renta dentro de los primeros diez días naturales del mes que corresponda, sobre el entendido que a partir del décimo primer día se acumularán al saldo insoluto, intereses moratorios, a razón del 4% (cuatro por ciento) mensual, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b255ba9b-992e-48d9-8df2-0090a357af0b', 'Incremento de Renta', '4', '5', 'AUMENTO DE RENTA', E'- The monthly sublease payment for the commercial area will increase every January.\n- The first increase will be in January 2027.\n- The increase will match the rise in the National Consumer Price Index published by INEGI or any replacement index for measuring inflation in Mexico.\n- Annual increases cannot exceed 8% of the current payment amount.', 'El importe de la contraprestación mensual por el subarrendamiento de EL ÁREA COMERCIAL se incrementará Anualmente, durante los meses de enero de cada año, siendo el primer incremento hasta el mes de enero del año 2027, en la misma proporción en que aumente el Índice Nacional de Precios al Consumidor que publique el INEGI (o el índice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos), en la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 8% del valor de la contraprestación vigente que opere en dicho período.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('b255ba9b-992e-48d9-8df2-0090a357af0b', 'Common Area Maintenance Charges', '5', '6', 'DEL MANTENIMIENTO Y PREVENCIÓN DE RIESGOS', E'- The subtenant must pay a maintenance fee equal to 10% of the current monthly rent. This payment starts when the business begins operations in the commercial area. This fee will include any applicable value-added tax (VAT) or any future tax that replaces it.\n- The subtenant will not contribute to the shopping center''s advertising expenses, so they will not be charged for advertising.\n- The subtenant is responsible for the care, upkeep, and maintenance of the commercial area and any installations they make, at their own expense, during the lease term.', E'Adicionalmente EL SUBARRENDATARIO deberá cubrir una cuota de mantenimiento equivalente al 10% de la renta mensual actual vigente, dicha cantidad se comenzará a pagar a partir de la apertura o inicio de operaciones del negocio que operará en EL ÁREA COMERCIAL, En el entendido que a dicha cantidad se le agregará el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a sustituirlo. \n\nLas Partes convienen que EL SUBARRENDATARIO no participará en los gastos de Publicidad del Centro Comercial por lo que no se generará cantidad alguno por concepto de publicidad a cargo de éste. \n\nEL SUBARRENDATARIO se obliga durante la vigencia del presente SUBARRENDAMIENTO, a su costa exclusiva, el cuidado, conservación y mantenimiento que requiera EL ÁREA COMERCIAL y las instalaciones que en ella realice.');
