ap_addr_2":"Sublancla 1","map_city_state_zip":"Libertad, Guadalupe, Nuevo León 67170","grid_brand":"Planet Fitness","location_created_at":"2025-09-26 19:23:05","active_lease_count_over_time":50954,"location_count_over_time":57800,"remaining_rent_liability_over_time":50954}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('3e87f917-d0ca-4d0e-b779-a6c137c55ae4', '92f80d69-c424-41e8-914b-f7d3fe283b15', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Lindavista Sublease: Inmuebles Jax, S.A. De C.V. (08/15/2022 - 08/14/2032)', NULL, true, 'activo', 'Lease', NULL, '2023-10-30', '2023-03-01', '2032-08-14', '2041-08-14', false, 2, NULL, 2, NULL, NULL, '2032-06-15', 'Send Notice to Renew', 119, 'Inmuebles Jax, S.A. De C.V.', NULL, NULL, '506 Calle Juan Ignacio Ramón', NULL, 'Monterrey', 'MX-NLE', '64000', 'MX', 'Cesar Alejandro Martinez Guerrero', NULL, NULL, 152, 'percent', NULL, NULL, 1000800, 'LA SUBARRENDATARIA deberá de pagar a la firma del presente contrato, el importe de 2 (dos) meses de RENTA MENSUAL, equivalente a $667,200.00 (Seiscientos sesenta y siete mil doscientos pesos 00/100 M.N.), más IVA (Impuesto al Valor Agregado), y el equivalente a un mes de renta, es decir la cantidad de $333,600.00 (Trescientos treinta y tres mil seiscientos pesos 00/100 M.N.) previos а la entrega del Inmueble, los cuales se aplicarán automáticamente, а los meses de renta seis, doce y dieciocho mismos que serán aplicables en el momento que se genere la obligación de pago de dicha renta atendiendo el periodo de gracia establecido en el presente contrato.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
