INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('3e87f917-d0ca-4d0e-b779-a6c137c55ae4', 'Late Fees', '13', '8', 'RENTA Y FORMA DE PAGO', E'- If the subtenant doesn''t pay the monthly rent on time, they will incur a penalty.\n- The penalty is 5% of the unpaid rent balance.\n- This penalty applies for each month the rent remains unpaid until the full amount is settled.', 'La falta de pago puntual de la RENTA MENSUAL de que se trate, generará а cargo de LA SUBARRENDATARIA una pena convencional equivalente al 5% (cinco por ciento) sobre el saldo insoluto de la RENTA MENSUAL, por cada mes de retraso en el pago de la RENTA MENSUAL y hasta en tanto dicho saldo insoluto no sea pagada en su totalidad.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('3e87f917-d0ca-4d0e-b779-a6c137c55ae4', 'Incremento de Renta', '11', '8', 'RENTA Y FORMA DE PAGO', E'- After one year from the Rent Payment Start Date, and annually thereafter, the monthly rent will increase based on the percentage increase of the National Consumer Price Index (INPC) from the previous 12 months.\n- The increase cannot exceed 10%.\n- If the increase is more than 16%, both parties will meet to agree on the new rent amount.', 'Transcurrido un año a partir de la Fecha de Inicio de Pago de la Renta y posteriormente de manera anual, la RENTA MENSUAL serán incrementadas anualmente en el mismo porcentaje de incremento que se haya registrado durante los últimos 12 (doce) meses inmediatos anteriores, el Índice Nacional de Precios al Consumidor (INPC) que publica el Instituto Nacional de Estadísticas y Geografía (INECI). En la inteligencia de que dichos aumentos no podrán ser mayores al 10%. Las partes acuerdan que si dicho incremento sea superior al 16%, Las Partes se reunirán y determinarán de común acuerdo el monto de la renta.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('3e87f917-d0ca-4d0e-b779-a6c137c55ae4', 'Common Area Maintenance Charges', '11', '8', 'RENTA Y FORMA DE PAGO', E'- The subtenant agrees to pay the sublandlord a rent of $333,600.00 MXN.\n- This amount is subject to applicable Value Added Tax (VAT).\n- The rent includes the maintenance fee for the shopping center.', 'LA SUBARRENDATARIA se obliga a pagar a EL SUBARRENDADOR por concepto de renta, la cantidad de $333,600.00 (Trescientos treinta y tres mil seiscientos pesos 00/100 M.N.), más el Impuesto al Valor Agregado correspondiente (en lo sucesivo la "RENTA MENSUAL"), misma que incluye la cuota de mantenimiento del Centro Comercial.');
