INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('451402d0-d845-40ca-bbb6-14e4361a828a', 'e11e0b35-feb5-412e-b07f-bd1a7704d2b7', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'San Luis Potosí (The Park) Sublease: SLP Retail Advisors, S. de R.L. de C.V. (02/01/2024 - 01/31/2029)', NULL, true, 'activo', 'Lease', NULL, '2024-02-01', '2023-10-21', '2029-01-31', '2039-01-31', false, 2, NULL, 2, NULL, NULL, '2028-11-02', 'Send Notice to Renew', 59, 'SLP Retail Advisors, S. de R.L. de C.V.', NULL, NULL, 'Paseo de la Reforma 2620', 'Piso 16', 'Lomas Altas', 'Ciudad de México', '11950', 'MX', 'Diego Noguera Lomelin | María Isabella Peloggio Ortiz', NULL, 'dnogueira@thorurbana.com | jpeloggio@thorurbana.com', NULL, 'percent', NULL, NULL, 655412, E'La Subarrendataria se obliga a entregar a la Subarrendadora, sin necesidad de requerimiento alguno, una cantidad equivalente a 2 (dos) meses del monto de la Renta Fija, más el IVA correspondiente, es decir, la cantidad de $655,412.00 (seiscientos cincuenta y cinco mil cuatrocientos doce pesos 00/100 M.N) más el IVA correspondiente (la "Renta Anticipada"), las cuales se pagarán de la siguiente manera:\n1.- La primera Renta Anticipada se pagará 15 (quince) días naturales posteriores a la fecha de entrega del Local. 2.- La segunda Renta Anticipada se pagará durante el Plazo de Gracia, antes de la apertura del Local.\n\nLa Renta Anticipada se recibirá en calidad de depósito y podrá ser aplicada para cubrir el primer y último mes respectivamente de operación del Local hasta donde alcance, en el entendido de que, en caso de que la Subarrendataria no abra el Local al público en la fecha acordada en este Contrato, dicha Renta Anticipada servirá como garantía de pago de una pena convencional por retraso en la apertura del Local al público, por lo que, desde este momento, la Subarrendataria autoriza a la Subarrendadora a retener dicha cantidad en concepto de pago de dicha pena convencional y a no aplicarlo al pago de Renta Mensual.', NULL, true, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"is_next_percent_rent_payment":"No"}'::jsonb);
